macro_rules! obligations_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function obligations in module {}", module_path!());
    };
}

mkfn!{
    obligations_introspect!();
    # [doc = " Returns the set of obligations needed to make `arg` well-formed."] # [doc = " If `arg` contains unresolved inference variables, this may include"] # [doc = " further WF obligations. However, if `arg` IS an unresolved"] # [doc = " inference variable, returns `None`, because we are not able to"] # [doc = " make any progress at all. This is to prevent cycles where we"] # [doc = " say \"?0 is WF if ?0 is WF\"."] pub fn obligations < 'tcx > (infcx : & InferCtxt < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , body_id : LocalDefId , recursion_depth : usize , term : Term < 'tcx > , span : Span ,) -> Option < PredicateObligations < 'tcx > > { let term = match term . kind () { TermKind :: Ty (ty) => { match ty . kind () { ty :: Infer (ty :: TyVar (_)) => { let resolved_ty = infcx . shallow_resolve (ty) ; if resolved_ty == ty { return None ; } else { resolved_ty } } _ => ty , } . into () } TermKind :: Const (ct) => { match ct . kind () { ty :: ConstKind :: Infer (_) => { let resolved = infcx . shallow_resolve_const (ct) ; if resolved == ct { return None ; } else { resolved } } _ => ct , } . into () } } ; let mut wf = WfPredicates { infcx , param_env , body_id , span , out : PredicateObligations :: new () , recursion_depth , item : None , } ; wf . add_wf_preds_for_term (term) ; debug ! ("wf::obligations({:?}, body_id={:?}) = {:?}" , term , body_id , wf . out) ; let result = wf . normalize (infcx) ; debug ! ("wf::obligations({:?}, body_id={:?}) ~~> {:?}" , term , body_id , result) ; Some (result) }
}

macro_rules! unnormalized_obligations_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function unnormalized_obligations in module {}", module_path!());
    };
}

mkfn!{
    unnormalized_obligations_introspect!();
    # [doc = " Compute the predicates that are required for a type to be well-formed."] # [doc = ""] # [doc = " This is only intended to be used in the new solver, since it does not"] # [doc = " take into account recursion depth or proper error-reporting spans."] pub fn unnormalized_obligations < 'tcx > (infcx : & InferCtxt < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , term : Term < 'tcx > , span : Span , body_id : LocalDefId ,) -> Option < PredicateObligations < 'tcx > > { debug_assert_eq ! (term , infcx . resolve_vars_if_possible (term)) ; if term . is_infer () { return None ; } let mut wf = WfPredicates { infcx , param_env , body_id , span , out : PredicateObligations :: new () , recursion_depth : 0 , item : None , } ; wf . add_wf_preds_for_term (term) ; Some (wf . out) }
}

macro_rules! trait_obligations_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function trait_obligations in module {}", module_path!());
    };
}

mkfn!{
    trait_obligations_introspect!();
    # [doc = " Returns the obligations that make this trait reference"] # [doc = " well-formed. For example, if there is a trait `Set` defined like"] # [doc = " `trait Set<K: Eq>`, then the trait bound `Foo: Set<Bar>` is WF"] # [doc = " if `Bar: Eq`."] pub fn trait_obligations < 'tcx > (infcx : & InferCtxt < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , body_id : LocalDefId , trait_pred : ty :: TraitPredicate < 'tcx > , span : Span , item : & 'tcx hir :: Item < 'tcx > ,) -> PredicateObligations < 'tcx > { let mut wf = WfPredicates { infcx , param_env , body_id , span , out : PredicateObligations :: new () , recursion_depth : 0 , item : Some (item) , } ; wf . add_wf_preds_for_trait_pred (trait_pred , Elaborate :: All) ; debug ! (obligations = ? wf . out) ; wf . normalize (infcx) }
}

