mkfn!{
    clause_obligations_introspect!();
    # [doc = " Returns the requirements for `clause` to be well-formed."] # [doc = ""] # [doc = " For example, if there is a trait `Set` defined like"] # [doc = " `trait Set<K: Eq>`, then the trait bound `Foo: Set<Bar>` is WF"] # [doc = " if `Bar: Eq`."] # [instrument (skip (infcx) , ret)] pub fn clause_obligations < 'tcx > (infcx : & InferCtxt < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , body_id : LocalDefId , clause : ty :: Clause < 'tcx > , span : Span ,) -> PredicateObligations < 'tcx > { let mut wf = WfPredicates { infcx , param_env , body_id , span , out : PredicateObligations :: new () , recursion_depth : 0 , item : None , } ; match clause . kind () . skip_binder () { ty :: ClauseKind :: Trait (t) => { wf . add_wf_preds_for_trait_pred (t , Elaborate :: None) ; } ty :: ClauseKind :: HostEffect (..) => { } ty :: ClauseKind :: RegionOutlives (..) => { } ty :: ClauseKind :: TypeOutlives (ty :: OutlivesPredicate (ty , _reg)) => { wf . add_wf_preds_for_term (ty . into ()) ; } ty :: ClauseKind :: Projection (t) => { wf . add_wf_preds_for_alias_term (t . projection_term) ; wf . add_wf_preds_for_term (t . term) ; } ty :: ClauseKind :: ConstArgHasType (ct , ty) => { wf . add_wf_preds_for_term (ct . into ()) ; wf . add_wf_preds_for_term (ty . into ()) ; } ty :: ClauseKind :: WellFormed (term) => { wf . add_wf_preds_for_term (term) ; } ty :: ClauseKind :: ConstEvaluatable (ct) => { wf . add_wf_preds_for_term (ct . into ()) ; } ty :: ClauseKind :: UnstableFeature (_) => { } } wf . normalize (infcx) }
}
mkitem!{mkstruct!{struct WfPredicates < 'a , 'tcx > { infcx : & 'a InferCtxt < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , body_id : LocalDefId , span : Span , out : PredicateObligations < 'tcx > , recursion_depth : usize , item : Option < & 'tcx hir :: Item < 'tcx > > , }}}
mkitem!{mkenum!{# [doc = " Controls whether we \"elaborate\" supertraits and so forth on the WF"] # [doc = " predicates. This is a kind of hack to address #43784. The"] # [doc = " underlying problem in that issue was a trait structure like:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " trait Foo: Copy { }"] # [doc = " trait Bar: Foo { }"] # [doc = " impl<T: Bar> Foo for T { }"] # [doc = " impl<T> Bar for T { }"] # [doc = " ```"] # [doc = ""] # [doc = " Here, in the `Foo` impl, we will check that `T: Copy` holds -- but"] # [doc = " we decide that this is true because `T: Bar` is in the"] # [doc = " where-clauses (and we can elaborate that to include `T:"] # [doc = " Copy`). This wouldn't be a problem, except that when we check the"] # [doc = " `Bar` impl, we decide that `T: Foo` must hold because of the `Foo`"] # [doc = " impl. And so nowhere did we check that `T: Copy` holds!"] # [doc = ""] # [doc = " To resolve this, we elaborate the WF requirements that must be"] # [doc = " proven when checking impls. This means that (e.g.) the `impl Bar"] # [doc = " for T` will be forced to prove not only that `T: Foo` but also `T:"] # [doc = " Copy` (which it won't be able to do, because there is no `Copy`"] # [doc = " impl for `T`)."] # [derive (Debug , PartialEq , Eq , Copy , Clone)] enum Elaborate { All , None , }}}

macro_rules! extend_cause_with_original_assoc_item_obligation_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function extend_cause_with_original_assoc_item_obligation in module {}", module_path!());
    };
}

mkfn!{
    extend_cause_with_original_assoc_item_obligation_introspect!();
    # [doc = " Points the cause span of a super predicate at the relevant associated type."] # [doc = ""] # [doc = " Given a trait impl item:"] # [doc = ""] # [doc = " ```ignore (incomplete)"] # [doc = " impl TargetTrait for TargetType {"] # [doc = "    type Assoc = SomeType;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " And a super predicate of `TargetTrait` that has any of the following forms:"] # [doc = ""] # [doc = " 1. `<OtherType as OtherTrait>::Assoc == <TargetType as TargetTrait>::Assoc`"] # [doc = " 2. `<<TargetType as TargetTrait>::Assoc as OtherTrait>::Assoc == OtherType`"] # [doc = " 3. `<TargetType as TargetTrait>::Assoc: OtherTrait`"] # [doc = ""] # [doc = " Replace the span of the cause with the span of the associated item:"] # [doc = ""] # [doc = " ```ignore (incomplete)"] # [doc = " impl TargetTrait for TargetType {"] # [doc = "     type Assoc = SomeType;"] # [doc = " //               ^^^^^^^^ this span"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Note that bounds that can be expressed as associated item bounds are **not**"] # [doc = " super predicates. This means that form 2 and 3 from above are only relevant if"] # [doc = " the [`GenericArgsRef`] of the projection type are not its identity arguments."] fn extend_cause_with_original_assoc_item_obligation < 'tcx > (tcx : TyCtxt < 'tcx > , item : Option < & hir :: Item < 'tcx > > , cause : & mut traits :: ObligationCause < 'tcx > , pred : ty :: Predicate < 'tcx > ,) { debug ! (? item , ? cause , ? pred , "extended_cause_with_original_assoc_item_obligation") ; let (items , impl_def_id) = match item { Some (hir :: Item { kind : hir :: ItemKind :: Impl (impl_) , owner_id , .. }) => { (impl_ . items , * owner_id) } _ => return , } ; let ty_to_impl_span = | ty : Ty < '_ > | { if let ty :: Alias (ty :: Projection , projection_ty) = ty . kind () && let Some (& impl_item_id) = tcx . impl_item_implementor_ids (impl_def_id) . get (& projection_ty . def_id) && let Some (impl_item) = items . iter () . find (| item | item . owner_id . to_def_id () == impl_item_id) { Some (tcx . hir_impl_item (* impl_item) . expect_type () . span) } else { None } } ; match pred . kind () . skip_binder () { ty :: PredicateKind :: Clause (ty :: ClauseKind :: Projection (proj)) => { if let Some (term_ty) = proj . term . as_type () && let Some (impl_item_span) = ty_to_impl_span (term_ty) { cause . span = impl_item_span ; } if let Some (impl_item_span) = ty_to_impl_span (proj . self_ty ()) { cause . span = impl_item_span ; } } ty :: PredicateKind :: Clause (ty :: ClauseKind :: Trait (pred)) => { debug ! ("extended_cause_with_original_assoc_item_obligation trait proj {:?}" , pred) ; if let Some (impl_item_span) = ty_to_impl_span (pred . self_ty ()) { cause . span = impl_item_span ; } } _ => { } } }
}
