macro_rules! object_region_bounds_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function object_region_bounds in module {}", module_path!());
    };
}

mkfn!{
    object_region_bounds_introspect!();
    # [doc = " Given an object type like `SomeTrait + Send`, computes the lifetime"] # [doc = " bounds that must hold on the elided self type. These are derived"] # [doc = " from the declarations of `SomeTrait`, `Send`, and friends -- if"] # [doc = " they declare `trait SomeTrait : 'static`, for example, then"] # [doc = " `'static` would appear in the list."] # [doc = ""] # [doc = " N.B., in some cases, particularly around higher-ranked bounds,"] # [doc = " this function returns a kind of conservative approximation."] # [doc = " That is, all regions returned by this function are definitely"] # [doc = " required, but there may be other region bounds that are not"] # [doc = " returned, as well as requirements like `for<'a> T: 'a`."] # [doc = ""] # [doc = " Requires that trait definitions have been processed so that we can"] # [doc = " elaborate predicates and walk supertraits."] pub fn object_region_bounds < 'tcx > (tcx : TyCtxt < 'tcx > , existential_predicates : & 'tcx ty :: List < ty :: PolyExistentialPredicate < 'tcx > > ,) -> Vec < ty :: Region < 'tcx > > { let erased_self_ty = tcx . types . trait_object_dummy_self ; let predicates = existential_predicates . iter () . map (| predicate | predicate . with_self_ty (tcx , erased_self_ty)) ; traits :: elaborate (tcx , predicates) . filter_map (| pred | { debug ! (? pred) ; match pred . kind () . skip_binder () { ty :: ClauseKind :: TypeOutlives (ty :: OutlivesPredicate (ref t , ref r)) => { if t == & erased_self_ty && ! r . has_escaping_bound_vars () { Some (* r) } else { None } } ty :: ClauseKind :: Trait (_) | ty :: ClauseKind :: HostEffect (..) | ty :: ClauseKind :: RegionOutlives (_) | ty :: ClauseKind :: Projection (_) | ty :: ClauseKind :: ConstArgHasType (_ , _) | ty :: ClauseKind :: WellFormed (_) | ty :: ClauseKind :: UnstableFeature (_) | ty :: ClauseKind :: ConstEvaluatable (_) => None , } }) . collect () }
}